import React, { useState } from "react";
import Layout from "../components/layout";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { graphql } from "gatsby";
import HeroBanner from "../components/heroBanner";
import images from "../images";
import { FaSquarePhone } from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import ContactForm from "../components/contactForm";
import Modal from "../components/modal";

const WhatWeDo: React.FC = () => {
  const { t } = useTranslation();
  const userData: UserProfile = data;
    const [isModalOpen, setIsModalOpen] = useState(false);
  

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <Layout data={userData}>
      <div className="w-full px-4">
        <HeroBanner
          backgroundImage={images.gallery_3.src}
          title="Ready to start?"
        >
          <p className="text-lg max-w-xl">
            Lorem ipsum dolor sit amet consectetur adipisicing elit. Quas quae
            explicabo provident fugit facilis enim dolores eos maxime totam
            debitis. Maxime, est. Veniam, nihil non debitis deserunt distinctio
            cupiditate eius!
          </p>
        </HeroBanner>
      </div>

      <div className="w-full px-4 flex flex-col sm:flex-row my-4 pb-0">
        <div className="w-full sm:w-3/4 h-96 sm:h-auto mb-4 sm:mb-0">
          <iframe className="w-full h-full"
            src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2799.76007872942!2d-73.49265032356459!3d45.434337535430515!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc90fa8e63c9c03%3A0xd81f311632cbabf6!2s9270%20Rue%20Riverin%2C%20Brossard%2C%20QC%20J4X%203A4!5e0!3m2!1ses!2sca!4v1748139868880!5m2!1ses!2sca"
            loading="lazy"
          ></iframe>
        </div>
        <div className="w-full sm:w-1/4 sm:h-auto mb-4 sm:mb-0 px-4">
          <h2 className="text-xl font-bold mb-5">{userData.name}</h2>
          <a className={styles.row} href={`tel:${userData.phone}`}>
            <FaSquarePhone /> {formatPhoneNumber(userData.phone)}
          </a>
          <p>{userData.address}</p>
          <p>
            {userData.city}, {userData.province}, {userData.postalCode}
          </p>
          <a className={`${styles.row} mb-5`} href={`mailto:${userData.email}`}>
            <MdEmail /> {userData.email}
          </a>
        </div>

      </div>

      <div className="flex mx-4 justify-center">
        <div className="my-5 w-full">
          <Modal isOpen={isModalOpen} setIsOpen={setIsModalOpen} buttonLabel="Tell us about your project" title="Tell us about your project">
            <ContactForm />
          </Modal>
        </div>    
      </div>

    </Layout>
  );
};
export default WhatWeDo;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  row: "flex flex-row gap-2 items-center",
};
